<template>
 <view class="wizard">
  <recruitment-conflict v-if="conflictSnapshot" :rows="conflictRows" :busy="busy" :can-replace="canReplace" :blocked-message="conflictBlockedMessage" :error="submitError" @close="closeConflict" @view="viewActive" @replace="replaceFromConflict"/>
  <app-toast :message="validationToast" type="error"/>
  <view class="steps" role="navigation" :aria-label="$t(&quot;ui.publishing_steps&quot;)"><view class="step-rail"><view class="step-progress" :style="{width:((step-1)/3*100)+'%'}"/></view>
   <button v-for="(name,index) in stepNames" :key="name" :class="{active:step===index+1,done:step>index+1}" :aria-current="step===index+1?'step':undefined" @click="go(index+1)"><text class="step-no">{{index+1}}</text><text>{{$t(name)}}</text></button>
  </view>
  <view v-if="saveFailed" class="draft-warning" role="status"><text>{{$t(saveIssue)}}</text><button @click="saveDraft">{{ $t("ui.retry_save") }}</button></view>
  <view v-if="step===1" class="wizard-panel">
   <view class="section-heading">{{ $t("recruitment.goal") }}<text>{{ $t("ui.choose_your_goal_for_this_session") }}</text></view>
   <view class="purpose-grid"><button v-for="g in GOALS" :key="g" :class="{chosen:form.goal===g}" :aria-pressed="form.goal===g" @click="form.goal=g"><b>{{$t(g)}}</b><text>{{$t(goalNotes[g])}}</text></button></view>
   <view v-if="errors.goal" class="error-line">{{$error(errors.goal)}}</view>
   <view v-if="form.goal==='goal.missions'" class="section-block"><view class="subheading">{{ $t("goal.missions") }} <text>{{ $t("ui.select_multiple") }}</text></view><view v-for="group in TASK_GROUPS" :key="group.label" class="task-group"><text class="muted-label">{{$t(group.label)}}</text><view class="chips"><button v-for="task in group.values" :key="task" :class="{chosen:form.tasks.includes(task)}" :aria-pressed="form.tasks.includes(task)" @click="toggleTask(task)">{{form.tasks.includes(task)?'✓ ':''}}{{$t(task)}}</button></view></view><view v-if="errors.tasks" class="error-line">{{$error(errors.tasks)}}</view></view>
   <view class="section-block"><view class="subheading">{{ $t("recruitment.slot") }}</view><view class="slot-field"><dark-select :model-value="form.slot" @update:model-value="selectSlot" :options="SLOT_OPTIONS" :label="$t(&quot;recruitment.slot&quot;)" :placeholder="$t(&quot;ui.select_a_play_time&quot;)" :invalid="!!errors.slot"/></view></view>
  </view>
  <view v-if="step===2" class="wizard-panel">
   <view class="section-heading">{{ $t("recruitment.maps") }}<text>{{ $t("ui.add_maps_and_choose_one_difficulty_for_each") }}</text></view>
   <view class="map-choices"><button v-for="map in Object.keys(MAP_MODES)" :key="map" :class="{chosen:hasMap(map)}" :aria-pressed="hasMap(map)" @click="toggleMap(map)" :title="hasMap(map)?$t(&quot;ui.click_to_deselect&quot;):$t(&quot;ui.click_to_select&quot;)">{{hasMap(map)?'✓':'＋'}} {{$t(map)}}</button></view>
   <view class="map-pairs">
   <view v-for="pair in form.maps" :key="pair.map" class="map-pair"><view class="pair-head"><b>{{$t(pair.map)}}</b><button :aria-label="$t(&quot;ui.remove&quot;)+$t(pair.map)" class="remove-map" @click="removeMap(pair.map)">×</button></view><view class="chips"><button v-for="mode in MAP_MODES[pair.map]" :key="mode" :class="{chosen:pair.difficulty===mode,night:mode==='difficulty.confidential_night'}" :aria-pressed="pair.difficulty===mode" @click="pair.difficulty=mode">{{$t(mode)}}</button></view></view>
   </view>
   <view v-if="!form.maps.length" class="empty-map">{{ $t("ui.select_the_maps_you_want_to_play_above") }}</view>
  </view>
  <view v-if="step===3" class="wizard-panel">
   <view class="section-heading">{{ $t("recruitment.self") }}<text>{{ $t("ui.your_profile_and_gear_for_this_session") }}</text></view>
   <view class="basic-info-section"><view class="basic-info-heading"><view class="subheading">{{ $t("profile.basic") }}<help-tooltip :label="$t(&quot;ui.about_sign_in_and_anonymous_play&quot;)" :text="$t(&quot;ui.sign_in_with_your_phone_to_restore_your_profile&quot;)"/></view><phone-login :profile="personalProfile" @restore="restoreProfile"/></view><view class="basic-grid"><label :class="{invalid:errors.nickname}"><view class="field-label">{{ $t("profile.nickname") }} <text class="required">*</text></view><input v-model="form.nickname" maxlength="24" :placeholder="$t(&quot;ui.what_should_teammates_call_you&quot;)" placeholder-style="color:#718096"/><text v-if="errors.nickname" class="error-line">{{$error(errors.nickname)}}</text></label><view v-for="field in baseFields" :key="field.key" class="basic-field">{{$t(field.label)}}<dark-select v-model="form[field.key]" :options="field.values" :label="$t(field.label)"  :option-labels="field.labels||{}" v-if="field.key!=='platform'"/><view v-else class="fixed-platform">{{$t("ui.pc")}}<text>{{$t("platform.pcOnly")}}</text></view></view><view class="basic-field" :class="{invalid:errors.style}">{{ $t("profile.playstyle") }} <text class="required">*</text><dark-select :model-value="form.style==null?'':String(form.style)" :options="styleOptions" :option-labels="styleOptionLabels" :label="$t(&quot;profile.playstyle&quot;)" :placeholder="$t('ui.select_your_playstyle')" :invalid="!!errors.style" @update:model-value="selectStyle"/><text v-if="errors.style" class="error-line">{{$error(errors.style)}}</text></view></view></view>
   <view v-if="needsGear" class="subheading section-block">{{ $t("profile.gear") }}</view>
   <view v-if="needsGear" class="gear-list"><view v-for="gear in GEAR_FIELDS" :key="gear.key" class="choice-row"><text class="row-label">{{$t(gear.label)}}</text><view class="level-group"><button v-for="n in 6" :key="n" :class="{chosen:form[gear.key]===n}" :aria-pressed="form[gear.key]===n" @click="form[gear.key]=n">{{n}}<text>{{ $t("unit.level") }}</text></button></view><view v-if="errors[gear.key]" class="error-line row-error">{{$error(errors[gear.key])}}</view></view></view>

   <view class="section-block strength-section"><view class="strength-heading"><view class="subheading strength-title">{{ $t("profile.combatStats") }}<text class="guidance">{{ $t("ui.enter_accurate_stats_large_skill_gaps_affect_both_players") }}</text></view></view>
    <view class="strength-values">
    <view class="stats-grid"><label v-for="field in scoreFields" :key="field.key" :class="{invalid:errors[field.key]}"><view class="field-label">{{$t(field.label)}}<text class="required">*</text><text v-if="empty(form[field.key])" class="missing">{{ $t("common.notEntered") }}</text></view><input v-model.number="form[field.key]" type="digit" :placeholder="$t(field.placeholder)" placeholder-style="color:#718096" @blur="checkField(field.key)"/><text v-if="errors[field.key]" class="error-line">{{$error(errors[field.key])}}</text></label></view>

    <strength-score :value="myScore"/>
    </view>
    <view v-if="scoreError" class="error-line" role="alert">{{$error(scoreError)}}<button class="score-retry" @click="calculateScore">{{ $t("ui.retry_calculation") }}</button></view>
   </view>
  </view>
  <view v-show="step===4" class="wizard-panel">
   <view class="section-heading">{{ $t("recruitment.partner") }}<text>{{ $t("ui.both_players_must_meet_each_other_s_requirements") }}</text></view>
   <view class="partner-ranges" role="group" :aria-label="$t(&quot;ui.teammate_playstyle_and_skill_ranges&quot;)">
    <view class="partner-range"><view class="subheading">{{ $t("ui.accepted_playstyles") }}<help-tooltip :label="$t(&quot;ui.about_playstyle_range&quot;)" :text="$t(&quot;ui.1_very_cautious_5_very_aggressive_your_teammate_s&quot;)"/></view><view class="style-bounds"><view v-for="bound in styleBounds" :key="bound.key" class="style-bound"><text class="muted-label">{{$t(bound.label)}}</text><view class="level-group"><button v-for="n in 5" :key="n" :class="{chosen:form[bound.key]===n}" :aria-label="$t(bound.label)+' '+$t(&quot;ui.playstyle_571&quot;)+n+$t(&quot;ui.level_582&quot;)" :aria-pressed="form[bound.key]===n" @click="form[bound.key]=n">{{n}}</button></view></view></view><view v-if="errors.partner_style" class="error-line">{{$error(errors.partner_style)}}</view></view>
    <strength-match-range :score="myScore" :active="step===4"/>

   </view>
   <view v-if="needsGear" class="section-block"><view class="subheading">{{ $t("ui.minimum_teammate_gear") }}<text>{{ $t("ui.no_higher_than_your_own_corresponding_gear") }}</text></view><view v-for="gear in GEAR_FIELDS" :key="gear.key" class="choice-row"><text class="row-label">{{$t(gear.label)}}</text><view class="level-group"><button v-for="n in 6" :key="n" :class="{chosen:form['partner_'+gear.key+'_min']===n}" :disabled="n>form[gear.key]" @click="form['partner_'+gear.key+'_min']=n">{{n}}<text>{{ $t("unit.level") }}</text></button></view><view v-if="errors['partner_'+gear.key+'_min']" class="error-line row-error">{{$error(errors['partner_'+gear.key+'_min'])}}</view></view></view>

   <view class="section-block recruitment-settings"><view class="subheading">{{ $t("recruitment.publishing") }}</view><view class="recruitment-settings-row"><view class="discovery-settings"><view class="settings-label"><text class="settings-title">{{ $t("recruitment.discovery") }}</text><help-tooltip :label="$t(&quot;ui.about_recruitment_modes&quot;)" :items="discoveryHelp"/></view><view class="mode-toggle" role="group" :aria-label="$t(&quot;recruitment.discovery&quot;)"><button :class="{chosen:form.discovery==='browse'}" :aria-pressed="form.discovery==='browse'" @click="form.discovery='browse'">{{ $t("discovery.browse") }}</button><button :class="{chosen:form.discovery==='auto'}" :aria-pressed="form.discovery==='auto'" @click="form.discovery='auto'">{{ $t("discovery.auto") }}</button></view></view><view class="visibility-settings"><text>{{ $t("ui.list_in_the_hall") }}</text><button class="visibility-toggle" :class="{enabled:form.public}" role="switch" :aria-checked="form.public" :aria-label="$t(&quot;ui.public_listing_132&quot;)" @click="form.public=!form.public"><text/></button></view></view></view>
  </view>
  <view v-if="preview" class="publish-overlay" @click.self="closePreview"><view class="publish-dialog" role="dialog" aria-modal="true" :aria-label="$t(&quot;ui.review_before_publishing&quot;)" tabindex="-1" @keydown.esc.stop="closePreview" @keydown.tab="trapPreviewFocus">
   <view class="publish-head"><view><b>{{ $t("ui.review_before_publishing") }}</b><text>{{ $t("ui.review_your_requirements_before_finding_a_teammate") }}</text></view><button class="preview-close" tabindex="0" :aria-label="$t(&quot;ui.close_preview&quot;)" :disabled="busy" @click="closePreview">×</button></view>
   <view class="publish-content">
    <view class="preview-line"><text class="preview-key">{{$t('listing.language')}}</text><view class="preview-tags"><text>{{$t(locale==='en'?'language.en':'language.zh')}}</text></view></view><view class="preview-line"><text class="preview-key">{{ $t("recruitment.goal") }}</text><view class="preview-tags"><text class="purpose-tag">{{$t(form.goal)}}</text></view></view>
    <view class="preview-line"><text class="preview-key">{{ $t("recruitment.maps") }}</text><view class="preview-tags"><text v-for="m in form.maps" :key="m.map">{{$t(m.map)}} · {{$t(m.difficulty)}}</text></view></view>
    <view v-if="form.goal==='goal.missions'" class="preview-line"><text class="preview-key">{{ $t("recruitment.tasks") }}</text><view class="preview-tags"><text v-for="task in form.tasks" :key="task">{{$t(task)}}</text></view></view>
    <view class="preview-comparison"><view class="preview-column"><view class="preview-column-title">{{ $t("ui.your_loadout") }}</view><view v-if="needsGear" class="preview-metric"><text>{{ $t("profile.gearLabel") }}</text><b>{{ $t("ui.helmet") }}{{form.helmet}} {{ $t("ui.armor_423") }}{{form.armor}} {{ $t("ui.ammo_424") }}{{form.ammo}}</b></view><view class="preview-metric"><text>{{ $t("profile.playstyleLabel") }}</text><b>{{form.style}} · {{$t(STYLE_LABELS[form.style-1])}}</b></view><view class="preview-metric"><text>{{ $t("profile.skill") }}</text><b>{{myScore}} {{ $t("unit.points") }}</b></view></view><view class="preview-column"><view class="preview-column-title">{{ $t("recruitment.partner") }}</view><view v-if="needsGear" class="preview-metric"><text>{{ $t("profile.gearLabel") }}</text><b>{{ $t("ui.helmet_155") }}{{form.partner_helmet_min}} {{ $t("ui.armor_603") }}{{form.partner_armor_min}} {{ $t("ui.ammo_604") }}{{form.partner_ammo_min}}</b></view><view class="preview-metric"><text>{{ $t("profile.playstyleLabel") }}</text><b>{{form.partner_style_min}}–{{form.partner_style_max}} {{ $t("unit.playstyle") }}</b></view><view class="preview-metric"><text>{{ $t("profile.skill") }}</text><b>{{range[0]}}–{{range[1]}} {{ $t("unit.points") }}</b></view></view></view>
    <view class="preview-summary">
     <view class="preview-line"><text class="preview-key">{{ $t("profile.basic") }}</text><view class="preview-tags"><text>{{form.nickname}}</text><text>{{form.region}}</text><text>{{{PC:$t("ui.pc"),Console:$t("ui.console"),Mobile:$t("ui.mobile")}[form.platform]}}</text><text>{{$t(locale==='en'?'language.en':'language.zh')}}</text><text>{{$t(form.voice)}}</text></view></view>
     <view class="preview-line"><text class="preview-key">{{ $t("recruitment.slot") }}</text><view class="preview-tags"><text>{{$t(form.slot)}}</text></view></view>
     <view class="preview-line"><text class="preview-key">{{ $t("recruitment.publishing") }}</text><view class="preview-tags"><text>{{form.discovery==='auto'?$t("discovery.auto"):$t("discovery.browse")}}</text><text>{{form.public?$t("visibility.public"):$t("visibility.private")}}</text></view></view>
    </view>
    <view v-if="submitError" class="preview-submit-error" role="alert">{{$error(submitError)}}</view>
   </view>
   <view class="publish-footer"><button tabindex="0" :disabled="busy" @click="closePreview">{{ $t("ui.edit") }}</button><button v-if="activeTicket" tabindex="0" class="publish-confirm" :disabled="busy" @click="openConflict">{{ $t("ui.submit_this_listing") }}</button><button v-else tabindex="0" class="publish-confirm" :disabled="busy" @click="finish">{{busy?$t("status.publishing"):$t("ui.publish")}}</button></view>
  </view></view>
  <view class="wizard-actions"><button class="save-draft" @click="saveDraft">{{saved?$t("ui.draft_saved"):$t("ui.save_draft")}}</button><view class="nav-buttons"><button v-if="step>1" @click="go(step-1)">{{ $t("action.back") }}</button><button v-if="activeTicket" class="primary" :disabled="busy" @click="openConflict">{{ $t("ui.submit_this_listing") }}</button><button v-else-if="step<4" class="primary" @click="next">{{ $t("action.next") }}</button><button v-else class="primary" :disabled="busy" @click="finish">{{busy?$t("status.publishing"):$t("ui.preview_listing")}}</button></view></view>
 </view>
</template>
<script setup>
import {publicationProfile} from '../utils/recruitment-locale.js'
import {locale,t} from '../i18n/index.js'
import {computed,reactive,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import {toleranceBounds} from '../utils/strength-range.js'
import RecruitmentConflict from './recruitment-conflict.vue'
import {recruitmentComparison} from '../utils/recruitment-comparison.js'
import AppToast from './app-toast.vue'
import DarkSelect from './dark-select.vue'
import StrengthScore from './strength-score.vue'
import StrengthMatchRange from './strength-match-range.vue'
import PhoneLogin from './phone-login.vue'
import HelpTooltip from './help-tooltip.vue'
import {MAP_MODES,GOALS,SLOT_OPTIONS,TASK_GROUPS,STYLE_LABELS,GEAR_FIELDS,scoreInputsValid} from '../utils/recruitment-options.js'
import {loadPreferences,savePreferencesDetailed,pickPreferences} from '../utils/pilot-preferences.js'
import {authRequest} from '../utils/pilot-session.js'
import {stepErrors} from '../utils/recruitment-validation.js'
const props=defineProps({busy:Boolean,activeTicket:Boolean,submitError:String,importProfile:Object,existingTicket:Object,squadStatus:String,resumeDraft:Object})
const emit=defineEmits(['submit','clear-error','view-active','replace','draft-change'])
const loaded=props.resumeDraft?{values:pickPreferences(props.resumeDraft),found:true}:loadPreferences(uni)
const form=reactive(loaded.values),step=ref(form.wizard_step),errors=ref({}),saveFailed=ref(false),saveIssue=ref(''),saved=ref(false),preview=ref(false)
const validationToast=ref('')
let validationToastTimer=null
function showValidation(found){const message=found.maps||found.slot;if(message){clearTimeout(validationToastTimer);validationToast.value=message;validationToastTimer=setTimeout(()=>{validationToast.value=''},6000)}}
onBeforeUnmount(()=>clearTimeout(validationToastTimer))
watch(step,()=>{clearTimeout(validationToastTimer);validationToast.value=''})
watch(()=>form.maps.map(m=>m.map+':'+m.difficulty).join('|'),()=>{if(!stepErrors(form,2).maps){clearTimeout(validationToastTimer);validationToast.value=''}})
let lastSaveError=''
watch(()=>props.importProfile,value=>{if(!value)return;Object.assign(form,pickPreferences({...value,wizard_step:1}));step.value=1;errors.value={};preview.value=false;persistDraft()},{immediate:true})
function persistDraft(){emit('draft-change',JSON.parse(JSON.stringify(form)));const result=savePreferencesDetailed(uni,form);saveFailed.value=!result.ok;saveIssue.value=result.message||'';const diagnostic=result.ok?'':result.stage+':'+result.errorName+':'+result.reason;if(diagnostic&&diagnostic!==lastSaveError)console.warn('[draft-save]',diagnostic);lastSaveError=diagnostic;return result.ok}
const discoveryHelp=[{id:'browse',title:'discovery.browse',description:'ui.browse_player_requirements_in_the_hall_and_send_a'},{id:'auto',title:'discovery.auto',description:'ui.find_an_online_player_who_also_uses_auto_match'},{id:'public',title:'ui.public_listing',description:'ui.when_enabled_others_can_find_your_listing_and_apply'}]
const styleBounds=[{key:'partner_style_min',label:'range.minimum'},{key:'partner_style_max',label:'range.maximum'}]
const stepNames=['recruitment.goal','recruitment.maps','recruitment.self','recruitment.partner']
const goalNotes={'goal.missions':'ui.complete_safe_related_missions','goal.budget_run':'ui.loot_with_minimal_gear','goal.loot_extract':'ui.gather_loot_and_pick_your_fights','goal.aggressive':'ui.seek_out_fights'}
const scoreFields=[{key:'confidential_kd',label:'metric.confidentialKd',placeholder:'ui.e_g_1_5'},{key:'top_secret_kd',label:'metric.topSecretKd',placeholder:'ui.e_g_2_0'},{key:'combat_score',label:'metric.combatScore',placeholder:'ui.e_g_50'}]
const baseFields=[{key:'region',label:'profile.region',values:['NA','EU','SEA','OCE','ME']},{key:'platform',label:'profile.platform',values:['PC'],labels:{PC:'ui.pc',Console:'ui.console',Mobile:'ui.mobile'}},{key:'voice',label:'profile.voice',values:['voice.mic','voice.listen']}]
const styleOptions=STYLE_LABELS.map((_,i)=>String(i+1))
const styleOptionLabels=computed(()=>Object.fromEntries(STYLE_LABELS.map((label,i)=>[String(i+1),t('profile.styleOption',{value:i+1,label:t(label)})])))
const personalKeys=['nickname','region','platform','voice','helmet','armor','ammo','style','confidential_kd','top_secret_kd','combat_score']
const personalProfile=computed(()=>Object.fromEntries(personalKeys.map(k=>[k,form[k]])))
function restoreProfile(values){form.style=null;form.style_explicit=false;for(const key of personalKeys.filter(key=>key!=='style'))if(Object.prototype.hasOwnProperty.call(values,key))form[key]=key==='platform'?'PC':values[key]??(['helmet','armor','ammo'].includes(key)?null:'')}
const needsGear=computed(()=>form.goal!=='goal.budget_run'),scoreResult=ref(null),scoreError=ref('')
const myScore=computed(()=>scoreResult.value?.strength_score??null),range=computed(()=>toleranceBounds(myScore.value,30))
const conflictSnapshot=ref(null)
const conflictRows=computed(()=>conflictSnapshot.value?recruitmentComparison(conflictSnapshot.value.profile,publicationProfile(form,locale.value),myScore.value,range.value):[])
const canReplace=computed(()=>!!conflictSnapshot.value&&props.existingTicket?.id===conflictSnapshot.value.id&&props.existingTicket?.status==='waiting'&&!['proposed','ready'].includes(props.squadStatus))
const conflictBlockedMessage=computed(()=>props.existingTicket?.status==='matched'||['proposed','ready'].includes(props.squadStatus)?'ui.a_teammate_has_been_found_please_review_your_current':props.existingTicket?.id!==conflictSnapshot.value?.id?'ui.your_listing_has_changed_review_the_current_listing_and':'ui.the_original_listing_has_ended_go_back_and_publish')
let scoreTimer=null,scoreRequest=0,scoreDisposed=false
const scoreKey=()=>JSON.stringify([form.confidential_kd,form.top_secret_kd,form.combat_score])
async function calculateScore(){
 clearTimeout(scoreTimer);const request=++scoreRequest,key=scoreKey();scoreError.value=''
 if(!scoreInputsValid(form)){scoreResult.value=null;return false}
 try{const result=await authRequest('strength-preview',Object.fromEntries(['confidential_kd','top_secret_kd','combat_score'].map(k=>[k,Number(form[k])])));if(scoreDisposed||request!==scoreRequest||key!==scoreKey())return false;scoreResult.value=result;return true}
 catch(e){if(!scoreDisposed&&request===scoreRequest){scoreResult.value=null;scoreError.value=e.message||'ui.could_not_calculate_your_score_please_retry'}return false}
}
watch(scoreKey,()=>{++scoreRequest;clearTimeout(scoreTimer);scoreResult.value=null;scoreError.value='';if(scoreInputsValid(form))scoreTimer=setTimeout(calculateScore,400)},{immediate:true})
onBeforeUnmount(()=>{scoreDisposed=true;++scoreRequest;clearTimeout(scoreTimer)})
const empty=n=>n===''||n==null
watch(form,()=>{saved.value=false;preview.value=false;persistDraft();if(Object.keys(errors.value).length)errors.value=stepErrors(form,step.value)},{deep:true,flush:'post'})
for(const gear of GEAR_FIELDS)watch(()=>form[gear.key],n=>{const k='partner_'+gear.key+'_min';if(n!=null&&form[k]>n)form[k]=null})
defineExpose({getDraft:()=>publicationProfile(JSON.parse(JSON.stringify(form)),locale.value)})
function saveDraft(){saved.value=persistDraft()}
function selectStyle(value){form.style=Number(value);form.style_explicit=true}
function selectSlot(value){form.slot=value;form.slot_explicit=true;clearTimeout(validationToastTimer);validationToast.value=''}
function toggleTask(task){form.tasks=form.tasks.includes(task)?form.tasks.filter(t=>t!==task):[...form.tasks,task]}
function hasMap(map){return form.maps.some(m=>m.map===map)}
function toggleMap(map){if(hasMap(map))removeMap(map);else form.maps.push({map,difficulty:''})}
function removeMap(map){form.maps=form.maps.filter(m=>m.map!==map)}
function scrollTop(){uni.pageScrollTo({scrollTop:0,duration:200})}
function go(n){if(n>step.value){for(let i=1;i<n;i++){const found=stepErrors(form,i);if(Object.keys(found).length){step.value=i;form.wizard_step=i;errors.value=found;preview.value=false;nextTick(()=>showValidation(found));scrollTop();return}}}step.value=n;form.wizard_step=n;errors.value={};preview.value=false;scrollTop()}
function next(){go(step.value+1)}
function checkField(key){const found=stepErrors(form,step.value);if(found[key])errors.value={...errors.value,[key]:found[key]}}
let oldBodyOverflow='',oldRootOverflow='',locked=false,previousFocus=null
function viewActive(){persistDraft();preview.value=false;conflictSnapshot.value=null;emit('view-active')}
async function openConflict(){if(props.busy)return;emit('clear-error');preview.value=false;await nextTick();if(!props.existingTicket){viewActive();return}conflictSnapshot.value=JSON.parse(JSON.stringify(props.existingTicket))}
function closeConflict(){if(props.busy)return;conflictSnapshot.value=null;emit('clear-error')}
async function replaceFromConflict(){if(props.busy||!canReplace.value)return;const expected=conflictSnapshot.value.id,payload=await preparePayload();if(!payload||props.busy)return;emit('replace',{expected_ticket_id:expected,profile:payload})}
function closePreview(){if(!props.busy)preview.value=false}
function unlockPreview(){if(!locked||typeof document==='undefined')return;document.body.style.overflow=oldBodyOverflow;document.documentElement.style.overflow=oldRootOverflow;locked=false;previousFocus?.focus?.()}
watch(preview,async shown=>{
 if(typeof document==='undefined')return
 if(shown){oldBodyOverflow=document.body.style.overflow;oldRootOverflow=document.documentElement.style.overflow;previousFocus=document.activeElement;document.body.style.overflow='hidden';document.documentElement.style.overflow='hidden';locked=true;await nextTick();document.querySelector('.publish-dialog')?.focus()}
 else unlockPreview()
})
function trapPreviewFocus(event){if(typeof document==='undefined')return;const elements=[...document.querySelectorAll('.publish-dialog [tabindex="0"]')].filter(el=>!el.hasAttribute('disabled'));if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===document.querySelector('.publish-dialog'))){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onBeforeUnmount(unlockPreview)
async function preparePayload(){
 for(let i=1;i<=4;i++){const found=stepErrors(form,i);if(Object.keys(found).length){step.value=i;form.wizard_step=i;errors.value=found;preview.value=false;conflictSnapshot.value=null;nextTick(()=>showValidation(found));scrollTop();return null}}
 if(myScore.value===null&&!await calculateScore()){step.value=3;form.wizard_step=3;conflictSnapshot.value=null;scrollTop();return null}
 const payload=publicationProfile(JSON.parse(JSON.stringify(form)),locale.value);delete payload.wizard_step;delete payload.slot_explicit;delete payload.style_explicit
 for(const key of ['manual_score','confidential_kd','top_secret_kd','combat_score','strength_min','strength_max'])if(payload[key]==='')payload[key]=null
 payload.score_mode='auto';payload.manual_score=null
 if(!needsGear.value)for(const gear of GEAR_FIELDS){payload[gear.key]=null;payload['partner_'+gear.key+'_min']=null}
 if(form.goal!=='goal.missions')payload.tasks=[]
 return payload
}
async function finish(){if(props.busy)return;if(props.activeTicket){await openConflict();return}const payload=await preparePayload();if(!payload)return;if(!preview.value){emit('clear-error');preview.value=true;return}if(!props.busy)emit('submit',payload)}
